css_extra:
.tone-dark { --turn:#DCE7E2; }
.display b, .h1 b { font-size:1.12em; letter-spacing:0; line-height:1; }
.tick i { background:url(assets/crown-colour.png) center/19px auto no-repeat; border-radius:0; width:22px; }
.tick i svg { display:none; }
.tone-dark .tick { background:#396735; border:1.5px solid rgba(255,255,255,.75); border-radius:6px; padding:12px 16px; align-items:center; }
.tone-dark .tick i { background-image:url(assets/crown-white.png); margin-top:0; }
.tone-dark .tick .body { color:#FFFFFF; font-weight:600; }
[data-name="Watermark"] svg { opacity:.16; }
.tone-dark [data-name="Watermark"] svg { filter:brightness(0) invert(1); opacity:.08; }
section[data-name^="Book"].tone-dark { background:linear-gradient(90deg,rgba(29,99,64,.97) 0%,rgba(29,99,64,.93) 48%,rgba(29,99,64,.6) 100%),url(assets/photos/s11-dup1.jpg) 50% 45%/cover no-repeat; }
.m section[data-name^="Book"].tone-dark { background:linear-gradient(180deg,rgba(29,99,64,.97) 0%,rgba(29,99,64,.9) 60%,rgba(29,99,64,.7) 100%),url(assets/photos/s11-dup1.jpg) 50% 45%/cover no-repeat; }
section[data-name="Final CTA"].tone-dark { background:linear-gradient(90deg,rgba(29,99,64,.98) 0%,rgba(29,99,64,.94) 50%,rgba(29,99,64,.72) 100%),url(assets/photos/s16.jpg) 50% 50%/cover no-repeat; }
.m section[data-name="Final CTA"].tone-dark { background:linear-gradient(180deg,rgba(29,99,64,.97) 0%,rgba(29,99,64,.95) 100%),url(assets/photos/s16.jpg) 50% 50%/cover no-repeat; }
.tone-light [data-name="Story"], .tone-light [data-name="Review"] { border:1px solid #DCE7E2; }
[data-name="Story"] > div:last-child > div:first-child { flex-wrap:wrap; gap:6px 12px; }
.btn { box-shadow:0 6px 14px rgba(16,38,27,.12); }
